(async()=>{
 const result=await ltCoordinator.cancelLoop(ltRun.id);
 ltRestoreLegacyConfig();
 const service=ltRequire(process.cwd()+'/dist/main/orchestration/cross-model-review-service.js').getCrossModelReviewService();service.runHeadlessReview=ltReviewOriginal;
 for(const {name,fn} of ltGateListeners)ltCoordinator.off(name,fn);
