 return {at:Date.now(),cancelled:result,status:current?.status,instances:ltManager.getAllInstances().length,pid:process.pid,versions:{electron:process.versions.electron,node:process.versions.node},metrics:ltRequire('electron').app.getAppMetrics().map(m=>({pid:m.pid,type:m.type})),wrappersRestored:true};
