import {spawn} from 'node:child_process';
import {openSync,appendFileSync} from 'node:fs';
const [name,...argv]=process.argv.slice(2);
const dir='docs/plans/2026-09-27-livetest-agent-runtime-residuals_evidence/2026-10-27-verifier-repair';
const start=new Date().toISOString();
const fd=openSync(dir+'/'+name+'.txt','w');
const child=spawn('rtk',['proxy',...argv],{stdio:['ignore',fd,fd]});
child.on('error',e=>{console.error(e.message);process.exitCode=1;});
child.on('exit',(code,signal)=>{appendFileSync(dir+'/commands.jsonl',JSON.stringify({start,end:new Date().toISOString(),argv,code,signal,log:name+'.txt'})+'\n');console.log(name+': exit '+code);process.exitCode=code??1;});

import {readFileSync,appendFileSync} from 'node:fs';
const mode=process.argv[2],file=process.argv[3];
const port=mode==='main'?9736:9735;
const targets=await(await fetch('http://127.0.0.1:'+port+'/json/list')).json();
const target=targets.find(t=>mode==='main'||t.type==='page');
const ws=new WebSocket(target.webSocketDebuggerUrl);await new Promise((r,j)=>{ws.onopen=r;ws.onerror=j;});
let id=0;const pending=new Map();
ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(m.error):p.resolve(m.result);}};
const send=(method,params={})=>new Promise((resolve,reject)=>{const i=++id;pending.set(i,{resolve,reject});ws.send(JSON.stringify({id:i,method,params}));});
try {
 if(mode!=='main'){await send('Emulation.setFocusEmulationEnabled',{enabled:true});try{await send('Emulation.setPageVisibilityOverride',{visibility:'visible'});}catch{}}
 const expression=readFileSync(file,'utf8');
 const result=await send('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true,timeout:700000});
 const receipt={at:new Date().toISOString(),mode,file,...result};
 appendFileSync('docs/plans/2026-09-27-livetest-agent-runtime-residuals_evidence/2026-10-27-verifier-repair/cdp.jsonl',JSON.stringify(receipt)+'\n');
 if(result.exceptionDetails){console.error(JSON.stringify(result.exceptionDetails));process.exitCode=1;}else console.log(JSON.stringify(result.result.value));
}finally{ws.close();}

(()=>{
 const names=['loop:fresh-eyes-review-started','loop:fresh-eyes-review-passed','loop:fresh-eyes-review-failed'];let removed=0;
 for(const n of names)for(const fn of ltCoordinator.listeners(n))if(fn.toString().includes('ltGateEvents')){ltCoordinator.off(n,fn);removed++;}
 globalThis.ltGatePriorEvents=ltGateEvents;globalThis.ltGateEvents=[];
 globalThis.ltGateListeners=names.map(name=>{const fn=p=>ltGateEvents.push({event:name,at:Date.now(),...p});ltCoordinator.on(name,fn);return {name,fn};});
 return {removed,attached:ltGateListeners.length,reason:'Remove duplicated passive probe listeners left by the two fixture starts; no product event or result is replaced.'};
})()

import {appendFileSync} from 'node:fs';
import assert from 'node:assert/strict';
const dir='docs/plans/2026-09-27-livetest-agent-runtime-residuals_evidence/2026-10-27-verifier-repair';
const tabs=await(await fetch('http://127.0.0.1:9735/json/list')).json();
const ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);
await new Promise((resolve,reject)=>{ws.onopen=resolve;ws.onerror=reject;});
let id=0;const pending=new Map();
ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(m.error):p.resolve(m.result);}};
const send=(method,params={})=>new Promise((resolve,reject)=>{const i=++id;pending.set(i,{resolve,reject});ws.send(JSON.stringify({id:i,method,params}));});
const evaluate=async expression=>{const r=await send('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.exceptionDetails)throw Error(r.exceptionDetails.text);return r.result.value;};
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const steps=[];let passed=false;
const state=async stage=>{await sleep(100);const d=await evaluate(`(()=>{const d=document.querySelector('.confirm-dialog');const a=document.activeElement;return {dialog:!!d,activeClass:a?.className,activeText:a?.textContent.trim(),inside:!!d?.contains(a),restored:a===window.ltFocusOpener};})()`);steps.push({stage,...d});return d;};
async function key(key,code,vk,shift=false){
 await send('Input.dispatchKeyEvent',{type:'keyDown',key,code,windowsVirtualKeyCode:vk,nativeVirtualKeyCode:vk,modifiers:shift?8:0});
 if(key==='Enter')await send('Input.dispatchKeyEvent',{type:'char',key,code,text:'\r',unmodifiedText:'\r',windowsVirtualKeyCode:vk,nativeVirtualKeyCode:vk});
 await send('Input.dispatchKeyEvent',{type:'keyUp',key,code,windowsVirtualKeyCode:vk,nativeVirtualKeyCode:vk,modifiers:shift?8:0});
}
try{
 await send('Emulation.setFocusEmulationEnabled',{enabled:true});
 try{await send('Emulation.setPageVisibilityOverride',{visibility:'visible'});}catch{}
 const visible=await evaluate(`({hidden:document.hidden,visibility:document.visibilityState})`);steps.push({stage:'visibility',...visible});assert.equal(visible.hidden,false);
 assert.equal(await evaluate(`(()=>{window.ltFocusOpener=document.querySelector('button.action-btn.terminate');window.ltFocusOpener?.focus();return !!window.ltFocusOpener;})()`),true);
 await key('Enter','Enter',13);assert.equal((await state('initial')).activeClass,'confirm-dialog');
 for(const [label,shift,expected] of [['tab1',false,'Keep running'],['tab2',false,'Close session'],['tab3',false,'Keep running'],['shiftTab',true,'Close session']]){
  await key('Tab','Tab',9,shift);const s=await state(label);assert.equal(s.inside,true);assert.equal(s.activeText,expected);
 }
 await key('Escape','Escape',27);const end=await state('escape');assert.equal(end.dialog,false);assert.equal(end.restored,true);passed=true;
}finally{
 const receipt={at:new Date().toISOString(),check:'AR-006-focus-current',passed,steps};
 appendFileSync(dir+'/focus.jsonl',JSON.stringify(receipt)+'\n');console.log(JSON.stringify(receipt));ws.close();
}

(()=>{
 const state=ltCoordinator.lifecycle.getState(ltRun.id);
 const iteration=ltCoordinator.getIterations(ltRun.id).at(-1);
 if(!['paused','running'].includes(state.status)||!iteration?.endedAt)throw Error('Non-terminal fixture not settled');
 const start=Date.now();globalThis.ltGateResult=null;
 globalThis.ltGatePromise=ltCoordinator.runFreshEyesReviewGate(state,'self-declared',iteration,'The builder made no further edits; review the one-line explanatory comment.').then(result=>{
  globalThis.ltGateResult={start,end:Date.now(),result,cached:state.freshEyesCleanForWorkState===true,anchored:!!state.freshEyesCleanWorkspaceDigest};
  return ltGateResult;
 });
 return {start,status:state.status,budget:state.config.completion.crossModelReview.timeoutSeconds,iteration:iteration.id};
})()

