})()

(async()=>{
 const types=ltRequire(process.cwd()+'/dist/shared/types/loop.types.js');
 const cwd=process.cwd()+'/_scratch/ar-final/fixture';
 const cfg=types.defaultLoopConfig(cwd,'The only requested change is a harmless explanatory comment above formatStorageBytes. The function behavior must remain unchanged. As builder, do not edit anything further, use no tools, and reply ACK only; do not declare completion.');
 cfg.provider='codex';cfg.model='gpt-5.6-terra';cfg.isolateLoopWorkspaces=false;
 cfg.caps.maxIterations=6;cfg.caps.maxWallTimeMs=900000;cfg.caps.capWrapUpIteration=false;
 cfg.completion.crossModelReview={...types.defaultCrossModelReviewConfig(),reviewers:['claude']};cfg.audit.finalAuditMode='off';
 globalThis.ltGateEvents=[];globalThis.ltGateListener=p=>ltGateEvents.push({at:Date.now(),...p});
 for(const n of ['loop:fresh-eyes-review-started','loop:fresh-eyes-review-passed','loop:fresh-eyes-review-failed'])ltCoordinator.on(n,ltGateListener);
 const service=ltRequire(process.cwd()+'/dist/main/orchestration/cross-model-review-service.js').getCrossModelReviewService();
 globalThis.ltReviewOriginal=service.runHeadlessReview;
 globalThis.ltReviewReceipts=[];
 service.runHeadlessReview=async function(request){
  const receipt={at:Date.now(),target:request.target,cwd:request.cwd,contentChars:request.content.length,timeout:request.timeoutSeconds,reviewers:request.reviewers};
  ltReviewReceipts.push(receipt);
  const result=await ltReviewOriginal.call(this,request);
  Object.assign(receipt,{endedAt:Date.now(),reviewers:result.reviewers,findings:result.findings.length,infrastructureErrors:result.infrastructureErrors});
  return result;
 };
 globalThis.ltRun=await ltCoordinator.startLoop('ar006-tiny-current',cfg);
 const pause=ltCoordinator.pauseLoop(ltRun.id);
 return {id:ltRun.id,status:ltRun.status,pause,caps:cfg.caps,review:cfg.completion.crossModelReview};
})()

